196	    /**
197	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
198	     * upper-cases the value, and expands common street-type abbreviations word-by-word
199	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
200	     * normalizes to the empty string. The normalized value is what the application stores, returns
201	     * and compares for household detection.
202	     *
203	     * @param address the raw address value from the request, may be {@code null}
204	     * @return the normalized address, or the empty string when none was supplied
205	     */
206	    private String normalizeAddress(String address) {
207	        if (address == null) {
208	            return "";
209	        }
210	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
211	        if (collapsed.isEmpty()) {
212	            return "";
213	        }
214	        String[] tokens = collapsed.split(" ");
215	        StringBuilder normalized = new StringBuilder();
216	        for (int i = 0; i < tokens.length; i++) {
217	            if (i > 0) {
218	                normalized.append(' ');
219	            }
220	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
221	        }
222	        return normalized.toString();
223	    }
