473	    /**
474	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
475	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
476	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
477	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
478	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
479	     * returned so the result is deterministic.
480	     *
481	     * @param owner the owner being created, with its normalized telephone already applied
482	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
483	     */
484	    private Owner findPossibleDuplicate(Owner owner) {
485	        String lastName = owner.getLastName();
486	        String postcode = owner.getPostcode();
487	        if (lastName == null || postcode == null) {
488	            return null;
489	        }
490	        String telephone = owner.getTelephone();
491	        return this.clinicService.findAllOwners().stream()
492	            .filter(OwnerRestControllerV1::isNotDeleted)
493	            .filter(existing -> postcode.equals(existing.getPostcode()))
494	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
495	            .filter(existing -> existing.getTelephone() == null
496	                || !existing.getTelephone().equals(telephone))
497	            .min(Comparator.comparingInt(Owner::getId))
498	            .orElse(null);
499	    }
