519	    /**
520	     * Rejects creating an owner once the given business day has already reached the maximum
521	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
522	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
523	     * registration date.
524	     *
525	     * @param registrationDate the business-day-adjusted registration date of the owner being created
526	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
527	     *     registered on that business day
528	     */
529	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
530	        long count = this.clinicService.findAllOwners().stream()
531	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
532	            .count();
533	        if (count >= DAILY_OWNER_LIMIT) {
534	            throw new DailyOwnerLimitException(registrationDate);
535	        }
536	    }
