538	    /**
539	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
540	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
541	     * been registered on that date. Evaluated before the new owner is persisted, so the count
542	     * reflects the owners that existed at the time of creation.
543	     *
544	     * @param registrationDate the business-day-adjusted registration date of the owner being created
545	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
546	     *     that registration date, otherwise {@code false}
547	     */
548	    private boolean isBulkSignup(LocalDate registrationDate) {
549	        long count = this.clinicService.findAllOwners().stream()
550	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
551	            .count();
552	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
553	    }
