555	    /**
556	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
557	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
558	     * date in the future is invalid.
559	     *
560	     * @param registrationDate the registration date supplied on the request, may be {@code null}
561	     * @throws InvalidFieldsException if the supplied date is later than today's server date
562	     */
563	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
564	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
565	            throw new InvalidFieldsException(List.of("registrationDate"));
566	        }
567	    }
