261	    /**
262	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
263	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
264	     * December belongs to the following calendar year's fiscal year and a date in January through
265	     * June belongs to its own calendar year's fiscal year.
266	     *
267	     * @param date the date to compute the fiscal year for
268	     * @return the fiscal year as a four-digit calendar year
269	     */
270	    private int fiscalYearValue(java.time.LocalDate date) {
271	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
272	    }
